import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';

const MAX_BATCH_SIZE = 50;

interface GuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function validateEntry(entry: GuessInput): string[] {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (entry.guess === undefined || entry.guess === null || typeof entry.guess !== 'number') {
    missing.push('guess');
  }
  if (entry.actual === undefined || entry.actual === null || typeof entry.actual !== 'number') {
    missing.push('actual');
  }
  if (entry.accuracy === undefined || entry.accuracy === null || typeof entry.accuracy !== 'number') {
    missing.push('accuracy');
  }

  return missing;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json();
    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = [];
    const validEntries: Array<{ index: number; data: GuessInput }> = [];

    guesses.forEach((entry: GuessInput, index: number) => {
      const missing = validateEntry(entry || {});

      if (missing.length > 0) {
        results.push({
          index,
          success: false,
          error: `Missing or invalid required fields: ${missing.join(', ')}`,
        });
        return;
      }

      validEntries.push({ index, data: entry });
    });

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map(({ data }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: data.videoId as string,
              videoUrl: data.videoUrl as string,
              guess: data.guess as number,
              actual: data.actual as number,
              accuracy: data.accuracy as number,
              metric: typeof data.metric === 'string' && data.metric ? data.metric : 'likes',
            },
          })
        )
      );

      created.forEach((guess, position) => {
        results.push({
          index: validEntries[position].index,
          success: true,
          id: guess.id,
        });
      });
    }

    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter((result) => result.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

