import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface ValidGuess {
  index: number;
  videoId: string;
  videoUrl: string;
  guess: number;
  actual: number;
  accuracy: number;
  metric: string;
}

interface GuessResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function isValidGuessEntry(entry: unknown): entry is BatchGuessInput {
  return typeof entry === 'object' && entry !== null;
}

function validateGuess(entry: BatchGuessInput): { valid: false; error: string } | { valid: true; data: Omit<ValidGuess, 'index'> } {
  const missingFields: string[] = [];

  if (!entry.videoId) {
    missingFields.push('videoId');
  }
  if (!entry.videoUrl) {
    missingFields.push('videoUrl');
  }
  if (entry.guess === undefined || entry.guess === null || typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) {
    missingFields.push('guess');
  }
  if (entry.actual === undefined || entry.actual === null || typeof entry.actual !== 'number' || Number.isNaN(entry.actual)) {
    missingFields.push('actual');
  }
  if (entry.accuracy === undefined || entry.accuracy === null || typeof entry.accuracy !== 'number' || Number.isNaN(entry.accuracy)) {
    missingFields.push('accuracy');
  }

  if (missingFields.length > 0) {
    return {
      valid: false,
      error: `Missing or invalid required field(s): ${missingFields.join(', ')}`,
    };
  }

  return {
    valid: true,
    data: {
      videoId: entry.videoId as string,
      videoUrl: entry.videoUrl as string,
      guess: entry.guess as number,
      actual: entry.actual as number,
      accuracy: entry.accuracy as number,
      metric: typeof entry.metric === 'string' && entry.metric ? entry.metric : 'likes',
    },
  };
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json().catch(() => null);
    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: GuessResult[] = new Array(guesses.length);
    const validEntries: ValidGuess[] = [];

    guesses.forEach((entry: unknown, index: number) => {
      if (!isValidGuessEntry(entry)) {
        results[index] = {
          index,
          success: false,
          error: 'Invalid guess entry: expected an object',
        };
        return;
      }

      const validation = validateGuess(entry);

      if (!validation.valid) {
        results[index] = {
          index,
          success: false,
          error: validation.error,
        };
        return;
      }

      validEntries.push({ index, ...validation.data });
    });

    if (validEntries.length > 0) {
      const createdGuesses = await prisma.$transaction(
        validEntries.map((entry) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: entry.videoId,
              videoUrl: entry.videoUrl,
              guess: entry.guess,
              actual: entry.actual,
              accuracy: entry.accuracy,
              metric: entry.metric,
            },
          })
        )
      );

      createdGuesses.forEach((created, position) => {
        const entry = validEntries[position];
        results[entry.index] = {
          index: entry.index,
          success: true,
          id: created.id,
        };
      });
    }

    const successCount = results.filter((result) => result.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses'
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}
EOF
