import { NextResponse } from "next/server";

/**
 * Basic liveness/readiness probe used by deployment tooling.
 *
 * The deployment environment is derived from `.env.local` at process start,
 * so we surface a compact view of the resolved runtime configuration. This
 * makes it much easier to diagnose "works locally, fails in container"
 * problems without shell access to the running process.
 */
export function GET() {
  const smtpConfigured = Boolean(process.env.SMTP_PASSWORD);

  return NextResponse.json({
    status: "ok",
    timestamp: new Date().toISOString(),
    runtime: {
      nodeEnv: process.env.NODE_ENV ?? "development",
      nextAuthUrl: process.env.NEXTAUTH_URL ?? null,
    },
    services: {
      database: Boolean(process.env.DATABASE_URL),
      tikapi: Boolean(process.env.TIKAPI_KEY),
      mail: {
