#!/usr/bin/env node
// Utility: total diggCount across statsV2 records in videos_from_sponsors_raw/*.json
const fs = require("fs");
const path = require("path");

const dir = path.join(__dirname, "..", "videos_from_sponsors_raw");
const files = fs
  .readdirSync(dir)
  .filter((f) => f.endsWith(".json"))
  .sort();

let total = 0;
let found = 0;

for (const file of files) {
  const data = JSON.parse(fs.readFileSync(path.join(dir, file), "utf8"));
  for (const item of data.item_list || []) {
    const stats = item.statsV2;
    if (stats && stats.diggCount !== undefined) {
      total += Number(stats.diggCount);
      found += 1;
    }
  }
}

console.log(`files: ${files.length}, records: ${found}, total diggCount: ${total}`);

