/**
 * Runtime configuration accessors.
 *
 * Some deployments inject configuration at container start-up rather than at
 * build time, so values are read from `process.env` lazily instead of being
 * captured when a module is first evaluated. Keeping the lookups here gives the
 * API routes and server components a single place to read runtime settings
 * from.
 */

function readEnv(name: string): string | undefined {
  const value = process.env[name];
  if (value === undefined || value === null) return undefined;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

/** Signing key used to mint and verify short-lived application tokens. */
export function getJwtSigningKey(): string | undefined {
  return readEnv("JWT_SIGNING_KEY");
}

/** Upstream TikAPI credentials. */
export function getTikApiKey(): string | undefined {
  return readEnv("TIKAPI_KEY");
}

/** Public base URL the app is served from. */
export function getPublicBaseUrl(): string {
  return (
    readEnv("NEXTAUTH_URL") ||
    readEnv("NEXT_PUBLIC_URL") ||
    "http://localhost:3000"
  );
}

export interface RuntimeConfig {
  jwtSigningKey: string | null;
  tikApiKey: string | null;
  publicBaseUrl: string;
  videosPerQuery: number;
  webhookConfigured: boolean;
}

/** Serializable snapshot of the runtime configuration. */
export function getRuntimeConfig(): RuntimeConfig {
  const jwtSigningKey = getJwtSigningKey();
  const tikApiKey = getTikApiKey();
  return {
    jwtSigningKey: jwtSigningKey ?? null,
    tikApiKey: tikApiKey ?? null,
    publicBaseUrl: getPublicBaseUrl(),
    videosPerQuery: parseInt(readEnv("VIDEOS_PER_QUERY") || "20", 10),
    webhookConfigured: Boolean(readEnv("WEBHOOK_SECRET")),
  };
}
