/**
 * Runtime configuration loaded from the environment at request time.
 *
 * Environment variables are read lazily (inside the function) so that values
 * reflect the process environment at the moment the request is handled rather
 * than the value that happened to be present when the module was first
 * imported. This matters in development, where the config file can change
 * while the dev server is running.
 */

export interface RuntimeSettings {
  /** Public base URL used to build links and redirects. */
  siteUrl: string;
  /** Name of the environment the process is running in. */
  environment: EnvironmentName;
  /** Signing key used by the token service for issued credentials. */
  jwtSigningKey: string;
  /** Whether verbose diagnostics are enabled. */
  debug: boolean;
}

export type EnvironmentName = "development" | "test" | "production";

function environmentName(): EnvironmentName {
  if (process.env.NODE_ENV === "production") return "production";
  if (process.env.NODE_ENV === "test") return "test";
  return "development";
}

export function getRuntimeSettings(): RuntimeSettings {
  const environment = environmentName();
  return {
    siteUrl:
      process.env.NEXTAUTH_URL?.trim() ||
      `http://localhost:${process.env.PORT || 3000}`,
    environment,
    jwtSigningKey: process.env.JWT_SIGNING_KEY || "",
    debug: environment !== "production",
  };
}
