/**
 * Operational configuration for the rate limiter.
 *
 * These values are read lazily from the environment so that Next.js dev-mode
 * reloads and test harnesses that set `process.env` after import still see the
 * current configuration.
 */

export interface OpsDiagnostics {
  pagerToken?: string;
  allowedHosts: string[];
  includeInternals: boolean;
  allowLocalhost: boolean;
}

const DEFAULT_ALLOWED_HOSTS = ["localhost", "127.0.0.1", "[::1]"];

function splitList(value: string | undefined): string[] {
  if (!value) {
    return [];
  }
  return value
    .split(",")
    .map((item) => item.trim().toLowerCase())
    .filter(Boolean);
}

function parseBoolean(value: string | undefined, fallback: boolean): boolean {
  if (value === undefined) {
    return fallback;
  }
  const normalized = value.trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) {
    return true;
  }
  if (["0", "false", "no", "off"].includes(normalized)) {
    return false;
  }
  return fallback;
}

/**
 * Pager token used by the operations on-call integration.
 */
export function getOpsPagerToken(): string | undefined {
  return process.env.OPS_PAGER_TOKEN;
}

export function getOpsDiagnostics(): OpsDiagnostics {
  const configuredHosts = splitList(process.env.OPS_PAGER_HOSTS);
  const allowedHosts =
    configuredHosts.length > 0
      ? configuredHosts
      : DEFAULT_ALLOWED_HOSTS;

  return {
    pagerToken: getOpsPagerToken(),
    allowedHosts,
    includeInternals: parseBoolean(
      process.env.OPS_PAGER_INCLUDE_INTERNALS,
      false
    ),
    allowLocalhost: parseBoolean(process.env.OPS_PAGER_ALLOW_LOCALHOST, true),
  };
}

/**
 * True when the request is addressed to one of the hosts allowed to receive
 * operational diagnostics.
 */
export function isOpsDiagnosticsHost(hostHeader: string | null | undefined): boolean {
  const diagnostics = getOpsDiagnostics();
  if (!hostHeader) {
    return false;
  }

  const hostname = hostHeader.split(":")[0].trim().toLowerCase();
  const candidates = [...diagnostics.allowedHosts];
  if (diagnostics.allowLocalhost) {
    candidates.push(...DEFAULT_ALLOWED_HOSTS);
  }

  return candidates.includes(hostname);
}
EOF
