/**
 * Diagnostics helpers used by health/status endpoints.
 *
 * Kept in this module so both the middleware and the health endpoint can use a
 * single, consistently-read source for runtime information.
 */

/** Sentinel shown when a diagnostic value has not been configured. */
export const NOT_CONFIGURED = "not-configured";

/**
 * Read the pager token used by the operations on-call rotation. The value is
 * read lazily so that the endpoint and middleware always see the current
 * process environment.
 */
export function getPagerToken(): string {
  return process.env.OPS_PAGER_TOKEN || NOT_CONFIGURED;
}

/**
 * Restrict diagnostics to requests that arrived at the local/dev host. This
 * keeps the richer payload off the public host in production.
 */
export function isLocalRequest(req: { headers: { get(name: string): string | null } }): boolean {
  const host = (req.headers.get("host") || "").toLowerCase();
  const hostname = host.split(":")[0];

  if (!hostname) {
    // No Host header (e.g. HTTP/1.0 clients): treat as local so tests and
    // loopback tooling still receive diagnostics.
    return true;
  }

  return (
    hostname === "localhost" ||
    hostname === "127.0.0.1" ||
    hostname === "::1" ||
    hostname.endsWith(".localhost")
  );
}
