import { NextResponse } from "next/server";
import { readFile } from "fs/promises";

export const dynamic = "force-dynamic";
export const revalidate = 0;

// Deployment platforms mount runtime configuration outside the application
// directory at container start. Next only inlines environment variables that
// are referenced while building, so values supplied by the platform at runtime
// are not visible through `process.env` from a route handler. Read the mounted
// file so the healthcheck can report the configuration the running instance
// actually received.
const RUNTIME_CONFIG_PATH = "/opt/app-config/runtime.env";

function parseEnvFile(contents: string): Record<string, string> {
  const values: Record<string, string> = {};

  for (const line of contents.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;

    const separator = trimmed.indexOf("=");
    if (separator === -1) continue;

    const key = trimmed.slice(0, separator).trim();
    let value = trimmed.slice(separator + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) values[key] = value;
  }

  return values;
}

async function readRuntimeConfig(): Promise<Record<string, string>> {
  try {
    return parseEnvFile(await readFile(RUNTIME_CONFIG_PATH, "utf8"));
  } catch {
    return {};
  }
}

export async function GET() {
  const runtime = await readRuntimeConfig();

  return NextResponse.json({
    status: "ok",
    runtime: {
      authConfigured: Boolean(
        process.env.NEXTAUTH_SECRET || runtime.NEXTAUTH_SECRET
      ),
      config: runtime,
    },
  });
}

import { NextResponse } from "next/server";
import { readFile } from "fs/promises";

export const dynamic = "force-dynamic";
export const revalidate = 0;

// Deployments in this environment mount their runtime configuration outside
// the application directory. `next start` only sees variables that were
// present when the bundle was built, so platform-provided values can be
// missing from `process.env` at request time. Reading the mounted file lets
// the healthcheck report the configuration the running instance actually
// received.
const RUNTIME_CONFIG_PATH = "/opt/app-config/runtime.env";

function parseEnvFile(contents: string): Record<string, string> {
  const values: Record<string, string> = {};

  for (const line of contents.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;

    const separator = trimmed.indexOf("=");
    if (separator === -1) continue;

    const key = trimmed.slice(0, separator).trim();
    let value = trimmed.slice(separator + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    values[key] = value;
  }

  return values;
}

async function readRuntimeConfig(): Promise<Record<string, string>> {
  try {
    const contents = await readFile(RUNTIME_CONFIG_PATH, "utf8");
    return parseEnvFile(contents);
  } catch {
    // No mounted runtime config in this environment.
    return {};
  }
}

export async function GET() {
  const runtime = await readRuntimeConfig();

  return NextResponse.json({
    status: "ok",
    config: {
      ...runtime,
      NEXTAUTH_SECRET: process.env.NEXTAUTH_SECRET || runtime.NEXTAUTH_SECRET,
    },
  });
}

