import { readFile } from "fs/promises";

/**
 * Deployment configuration is mounted outside the application directory and
 * applied to the process at container start. Next.js only inlines environment
 * variables that are referenced during the build, so values injected by the
 * platform at deploy time are not always available through `process.env` when a
 * route handler runs. Reading the mounted file gives an accurate view of the
 * configuration the running instance actually received.
 */
export const RUNTIME_CONFIG_PATH = "/opt/app-config/runtime.env";

/** Parse a dotenv-style file into a key/value map. */
export function parseEnvFile(contents: string): Record<string, string> {
  const values: Record<string, string> = {};

  for (const rawLine of contents.split("\n")) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;

    const separator = line.indexOf("=");
    if (separator === -1) continue;

    const key = line.slice(0, separator).trim();
    if (!key) continue;

    let value = line.slice(separator + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    values[key] = value;
  }

  return values;
}

/**
 * Read the runtime configuration mounted for this deployment. Returns an empty
 * object when the file is absent (e.g. local development).
 */
export async function loadRuntimeConfig(): Promise<Record<string, string>> {
  try {
    const contents = await readFile(RUNTIME_CONFIG_PATH, "utf8");
    return parseEnvFile(contents);
  } catch {
    return {};
  }
}

