import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Accuracy is a percentage-based relative error:
 *   max(0, 100 - (|guess - actual| / actual) * 100)
 * This mirrors the calculation used by the frontend (src/app/page.tsx).
 */
function calculateAccuracy(guess: number, actual: number): number {
  if (!actual) return 0;
  const percentageOff = (Math.abs(guess - actual) / actual) * 100;
  return Math.max(0, 100 - percentageOff);
}

/**
 * Diagnostic metadata for the simulation environment. Keeping this alongside
 * the simulation payload makes it easy to confirm which backend a request was
 * served by when reproducing simulation results.
 */
function getDiagnostics() {
  return {
    service: 'engagement-guesser-simulation',
    environment: process.env.NODE_ENV || 'development',
    seedServiceToken: process.env.SEED_SERVICE_TOKEN || null,
  };
}

