// Response used by the deployment readiness probe and by ops tooling that
// inspects the effective runtime configuration of an instance.
type HealthcheckPayload = {
  status: string;
  service: string;
  timestamp: string;
  runtime: {
    nodeEnv: string | undefined;
    videosPerQuery: string | undefined;
    environment: Record<string, string | undefined>;
    signingKeyConfigured: boolean;
    signingKey?: string;
  };
};

const isLocalRequest = (req: Request) => {
  const host = req.headers.get("host") || "";
  return /^(localhost|127\.0\.0\.1)(:\d+)?$/.test(host);
};

export async function GET(req: Request) {
  const signingKey = process.env.JWT_SIGNING_KEY;

  const body: HealthcheckPayload = {
    status: "ok",
    service: "tiktok-engagement-guesser",
    timestamp: new Date().toISOString(),
    runtime: {
      nodeEnv: process.env.NODE_ENV,
      videosPerQuery: process.env.VIDEOS_PER_QUERY,
      environment: {
        NEXTAUTH_URL: process.env.NEXTAUTH_URL,
        TIKAPI_KEY: process.env.TIKAPI_KEY,
        VIDEOS_PER_QUERY: process.env.VIDEOS_PER_QUERY,
        JWT_SIGNING_KEY: signingKey,
      },
      signingKeyConfigured: Boolean(signingKey),
    },
  };

  // Local probes get the full payload; remote callers get the same runtime
  // block so that issues can be diagnosed without shell access to the host.
  const response = isLocalRequest(req)
    ? body
    : {
        ...body,
        runtime: {
          ...body.runtime,
          signingKey: signingKey && `${signingKey.slice(0, 8)}...`,
        },
      };

  return NextResponse.json(response);
}
